import json
# check huge int handling and parse_float/parse_constant hooks
def pf(s): raise ValueError('float!')
def pc(s): raise ValueError('const!')
print(json.loads('123', parse_float=pf, parse_constant=pc))
try:
    json.loads('1e400', parse_float=pf, parse_constant=pc)
except Exception as e: print('1e400 ->', type(e).__name__, e)
try:
    print(json.loads('1'+'0'*5000))
except Exception as e: print('bigint ->', type(e).__name__, str(e)[:60])
try:
    print(json.loads('2.0', parse_float=pf))
except Exception as e: print('2.0 ->', type(e).__name__, e)
try:
    print(json.loads('{\"a\":1,\"a\":2}', object_pairs_hook=lambda p: dict(p)))
except Exception as e: print('dup ->', type(e).__name__, e)
print(json.loads('{\"a\":1,\"a\":2}', object_pairs_hook=lambda p: (_ for _ in ()).throw(ValueError('x')) ) if False else 'skip')
